/* ============ SECCIÓN 4 · Los nueve exámenes reales, resueltos ============ */

registerExercises('fiuba-quimica-libre', '4', [

  {st: 'Parcial Curso 1, 31/05/24, Ej. 1a. La reacción es 2 NH<sub>3</sub>(g) + 4 O<sub>2</sub>(g) → N<sub>2</sub>O<sub>5</sub>(g) + 3 H<sub>2</sub>O(g). Reaccionan 0,044 mol de NH<sub>3</sub> con rendimiento del 90 %. ¿Cuántos litros de vapor de agua se forman a 125 °C y 1 atm?',
   opts: ['1,94 L', '2,16 L', '1,33 L', '0,61 L'],
   c: 0,
   ex: 'n(H<sub>2</sub>O) = 0,044 × (3/2) × 0,90 = <b>0,0594 mol</b> ▸ V = nRT/P = 0,0594 × 0,0821 × 398,15 / 1 = <b>1,94 L</b>. ▸ <b>2,16 L</b> es lo que da si te olvidás del rendimiento (0,066 mol): el 90 % se aplica <b>al producto</b>, siempre. ▸ <b>1,33 L</b> sale de usar 22,4 L/mol, que vale sólo en <b>CNPT</b> (0 °C y 1 atm): acá la temperatura es 125 °C, así que hay que ir por nRT/P. ▸ <b>0,61 L</b> es meter 125 en la ecuación de estado sin pasar a kelvin: la T va <b>siempre en K</b>. ▸ Coherencia dimensional: con la presión en atm va R = 0,0821 L·atm/mol·K, no 8,31.'},

  {st: 'Parcial Curso 1, Ej. 2a. Te dan ΔH°<sub>f</sub>(CO<sub>2</sub>) = −393,5 kJ/mol y te piden la entalpía de combustión del carbón, C(s) + O<sub>2</sub>(g) → CO<sub>2</sub>(g). ¿Cuánto vale?',
   opts: ['Hay que buscar la ΔH°<sub>f</sub> del carbón en la tabla periódica', '−393,5 kJ/mol: es la propia ΔH°<sub>f</sub> del CO<sub>2</sub>', '−787,0 kJ/mol, porque hay que sumar el O<sub>2</sub>', 'No se puede calcular con los datos del enunciado'],
   c: 1,
   ex: 'La reacción de combustión del carbón <b>es exactamente la reacción de formación del CO<sub>2</sub></b>: un elemento en su estado estándar más O<sub>2</sub> dando el compuesto. Por eso ΔH°<sub>comb</sub>(C) = ΔH°<sub>f</sub>(CO<sub>2</sub>) = <b>−393,5 kJ/mol</b>, sin hacer cuentas. ▸ La ΔH°<sub>f</sub> del carbón no se busca: <b>vale cero por definición</b>, como la de todo elemento en su estado estándar (y lo mismo el O<sub>2</sub>). ▸ Los −787,0 son 2 × (−393,5), que no viene de ningún lado acá. ▸ Reconocer esto vale la mitad del ítem a) en los tres parciales de curso, porque los tres comparan un hidrocarburo con carbón.'},

  {st: 'Parcial Curso 1, Ej. 2b. «Si la combustión del etano se realiza a P y T constantes, indique si el sistema realiza trabajo sobre el entorno o el entorno sobre el sistema». La ecuación es C<sub>2</sub>H<sub>6</sub>(g) + 7/2 O<sub>2</sub>(g) → 2 CO<sub>2</sub>(g) + 3 H<sub>2</sub>O(l).',
   opts: ['El sistema sobre el entorno, porque se libera calor', 'El entorno sobre el sistema, porque Δn<sub>gas</sub> = −2,5 y el sistema se contrae', 'No hay trabajo, porque la presión es constante', 'El sistema sobre el entorno, porque Δn<sub>gas</sub> = +0,5'],
   c: 1,
   ex: 'Contás moles de gas <b>ignorando líquidos y sólidos</b>: reactivos 1 + 3,5 = 4,5; productos 2, porque el agua es <b>líquida</b> ▸ Δn<sub>gas</sub> = <b>−2,5</b>. El volumen baja, así que el entorno comprime: <b>w = −Δn·R·T = +6,19 kJ/mol</b>, positivo, entra trabajo al sistema. ▸ El calor liberado es ΔH y no dice nada sobre el signo del trabajo: son dos términos distintos de ΔU = q + w. ▸ Que la presión sea constante no anula el trabajo, lo hace calculable: w = −PΔV = −Δn<sub>gas</sub>RT. ▸ El +0,5 sale de contar el agua como gas; el enunciado da ΔH°<sub>f</sub> de H<sub>2</sub>O(<b>l</b>).'},

  {st: 'Parcial Curso 1, Ej. 3c. Con el dato del examen (pK<sub>a</sub> = 6,5) la concentración mínima de ácido benzoico para pH 4,0 es 3,17·10<sup>-2</sup> M. ¿Qué concentración de HCl da el mismo pH?',
   opts: ['3,17·10<sup>-2</sup> M, la misma', '1,0·10<sup>-4</sup> M', '3,16·10<sup>-7</sup> M', '1,0·10<sup>-10</sup> M'],
   c: 1,
   ex: 'El HCl es <b>ácido fuerte</b>: se disocia totalmente, así que su concentración inicial <b>es</b> la de protones. Para pH 4,0, C = [H<sup>+</sup>] = <b>1,0·10<sup>-4</sup> M</b>. ▸ La respuesta conceptual del ítem es el cociente: hacen falta <b>317 veces menos</b> HCl que ácido benzoico para el mismo pH, porque el débil sólo entrega el 0,32 % de sus protones. ▸ Poner la misma concentración es justamente el error que el ítem detecta: si las concentraciones fueran iguales, el fuerte daría un pH mucho más bajo. ▸ El 3,16·10<sup>-7</sup> es K<sub>a</sub>, no una concentración. ▸ El 1,0·10<sup>-10</sup> es [OH<sup>-</sup>] a ese pH.'},

  {st: 'Parcial Curso 2, Ej. 1b. Reacción: 2 NaCl(s) + H<sub>2</sub>SO<sub>4</sub>(ac) → Na<sub>2</sub>SO<sub>4</sub>(ac) + 2 HCl(ac). Se forman 3,66 mol de HCl y se usan 500 g de NaCl al 71 % de pureza. ¿Cuál es el reactivo limitante y cuánto sobra del otro?',
   opts: ['Limitante el NaCl; sobran 1,83 mol de H<sub>2</sub>SO<sub>4</sub>', 'Limitante el H<sub>2</sub>SO<sub>4</sub>; sobran 2,41 mol de NaCl', 'Limitante el NaCl; sobran 2,41 mol de H<sub>2</sub>SO<sub>4</sub>', 'Limitante el H<sub>2</sub>SO<sub>4</sub>; sobran 4,90 mol de NaCl'],
   c: 1,
   ex: 'NaCl puro = 500 × 0,71 = 355 g ▸ n = 355 / 58,44 = <b>6,075 mol</b>. Para formar 3,66 mol de HCl hacen falta 3,66 mol de NaCl y 1,83 mol de H<sub>2</sub>SO<sub>4</sub>. Como hay 6,075 mol de NaCl y sólo se consumen 3,66, el <b>NaCl está en exceso</b> y el limitante es el <b>H<sub>2</sub>SO<sub>4</sub></b>; sobran 6,075 − 3,66 = <b>2,41 mol de NaCl</b>. ▸ Los 4,90 mol salen de olvidar la pureza y usar los 500 g enteros (8,56 mol). ▸ Y ojo con la relación 2:1: el NaCl va con coeficiente <b>2</b>, así que consumís tantos moles de NaCl como de HCl formado, no la mitad.'},

  {st: 'Parcial Curso 2, Ej. 3b. Para el amoníaco a pH 10,5 con pK<sub>b</sub> = 4,74 el grado de ionización da α = 5,44 %. ¿Qué implica ese número para la resolución?',
   opts: ['Nada: la aproximación C − x ≈ C siempre vale para electrolitos débiles', 'Que la aproximación queda al límite y conviene hacer la cuenta exacta y declararlo', 'Que el amoníaco es en realidad una base fuerte', 'Que hay que recalcular usando K<sub>a</sub> en vez de K<sub>b</sub>'],
   c: 1,
   ex: 'La regla habitual habilita «C − x ≈ C» mientras <b>α &lt; 5 %</b>, y acá da <b>5,44 %</b>: justo por encima. La aproximación pura da C = 5,50·10<sup>-3</sup> M y el cálculo exacto <b>5,81·10<sup>-3</sup> M</b>, un 5,7 % de diferencia. ▸ Como el ítem a) pide literalmente «<i>explicitando las suposiciones que realiza en los cálculos</i>», acá se cobra el criterio: hacé la exacta, mostrá la aproximada y decí que queda al límite. ▸ Es el único de los tres parciales de curso donde pasa: en el Curso 1 α = 0,32 % y en el Curso 3 α = 0,46 %. ▸ Un α del 5 % no convierte a nadie en electrolito fuerte: fuerte significa disociación total, α ≈ 100 %.'},

  {st: 'Parcial Curso 3, Ej. 2a. El enunciado dice «Calcule las entalpías de combustión <b>del etano</b> y del carbón», pero la tabla de datos del mismo ejercicio trae C<sub>3</sub>H<sub>8</sub>(g) con ΔH°<sub>f</sub> = −103,85 kJ/mol y el ítem b) habla de «la combustión del propano». ¿Qué hacés?',
   opts: ['Resolvés con etano y pedís el dato al docente', 'Resolvés con propano, transcribís la errata y aclarás por qué', 'Dejás el ítem en blanco porque el enunciado es contradictorio', 'Resolvés los dos, etano y propano, para cubrirte'],
   c: 1,
   ex: 'Es una <b>errata de copia</b> del parcial del Curso 1, cuyo combustible sí es etano. En el Curso 3 todo lo demás apunta a propano: el encabezado del ejercicio («un secadero de nueces está evaluando si usar <b>propano</b>»), la tabla de datos y el ítem b). ▸ Además el enunciado <b>se autocorrige por falta de datos</b>: no te dan la ΔH°<sub>f</sub> del etano, así que con etano el ítem es irresoluble. ▸ Dejarlo en blanco es lo peor que podés hacer: el Ejercicio 2 vale 35 puntos y hay que resolver al menos el 50 % de <b>cada</b> ejercicio para aprobar. ▸ Resolver los dos gasta tiempo sin sumar: lo que suma es una línea al margen declarando el criterio.'},

  {st: '1er Recuperatorio, 14/06/24, Ej. 1b. Se obtienen 3,12·10<sup>-2</sup> mol de CaO que se disuelven en 10 L de agua formando Ca(OH)<sub>2</sub>. ¿Cuál es el pH de la solución?',
   opts: ['11,49', '11,80', '2,20', '12,80'],
   c: 1,
   ex: 'M(Ca(OH)<sub>2</sub>) = 3,12·10<sup>-2</sup> / 10 = <b>3,12·10<sup>-3</sup> M</b>, pero el hidróxido de calcio aporta <b>2 OH<sup>-</sup> por fórmula</b> ▸ [OH<sup>-</sup>] = <b>6,24·10<sup>-3</sup> M</b> ▸ pOH = 2,20 ▸ pH = <b>11,80</b>. ▸ El <b>11,49</b> es exactamente lo que da si te olvidás del 2: es el error más frecuente del ítem y acecha en tres de los nueve exámenes, con Ca(OH)<sub>2</sub>, Ba(OH)<sub>2</sub> o Mg(OH)<sub>2</sub>. ▸ El <b>2,20</b> es el pOH informado como si fuera pH. ▸ El <b>12,80</b> sale de dividir por 1 L en vez de por los 10 L de agua del enunciado. ▸ Sumá la aclaración que vale puntos: a 3,12·10<sup>-3</sup> M el Ca(OH)<sub>2</sub> está por debajo de su solubilidad (≈ 2·10<sup>-2</sup> M a 25 °C), así que se disuelve todo y se lo trata como base fuerte totalmente disociada.'},

  {st: '1er Recuperatorio, Ej. 2c. Para C<sub>5</sub>H<sub>12</sub>(l) + 8 O<sub>2</sub>(g) → 5 CO<sub>2</sub>(g) + 6 H<sub>2</sub>O(l) con ΔH°<sub>comb</sub> = −3537,06 kJ/mol a 25 °C, ¿cuánto vale ΔU?',
   opts: ['−3529,63 kJ/mol', '−3544,49 kJ/mol', '−3537,06 kJ/mol, igual que ΔH', '+3895,8 kJ/mol'],
   c: 0,
   ex: 'ΔU = ΔH − Δn<sub>gas</sub>·R·T, con Δn<sub>gas</sub> = 5 − 8 = <b>−3</b> (el combustible y el agua son <b>líquidos</b>: no cuentan). Δn·R·T = (−3)(8,31·10<sup>-3</sup>)(298,15) = −7,43 kJ/mol ▸ ΔU = −3537,06 + 7,43 = <b>−3529,63 kJ/mol</b>. ▸ El <b>−3544,49</b> es el mismo cálculo con el signo cambiado, y es lo que también sale si contás el agua como gas (Δn = +3): como el sistema <b>se contrae</b>, el entorno hace trabajo sobre él y por eso tiene que dar <b>|ΔU| &lt; |ΔH|</b>. ▸ Decir que son iguales es correcto sólo como aproximación: la diferencia es el 0,2 %, pero el ítem pide el número y la justificación. ▸ El <b>+3895,8</b> es el error de unidades: 3 × 8,31 × 298,15 son <b>7433 J</b>, o sea 7,43 <b>kJ</b>; sumarlos como si fueran kJ da un ΔU positivo para una combustión, que es absurdo.'},

  {st: '1er Recuperatorio, Ej. 3a. Para C(s) + H<sub>2</sub>O(g) ⇌ CO(g) + H<sub>2</sub>(g) a 800 °C, K<sub>p</sub> = 14,28. En 500 L se cargan 10 kg de carbón, 50 mol de H<sub>2</sub>O(g), 10 mol de CO y 30 mol de H<sub>2</sub>. ¿Se obtendrá más hidrógeno?',
   opts: ['No, porque ya hay hidrógeno cargado y el sistema va hacia reactivos', 'Sí, porque Q<sub>p</sub> = 1,06 &lt; K<sub>p</sub> = 14,28', 'No se puede decidir sin conocer la masa de carbón que reacciona', 'Sí, porque hay carbón en exceso'],
   c: 1,
   ex: 'Con RT/V = 0,0821 × 1073,15 / 500 = 0,17621 atm/mol, las presiones parciales son 8,811 · 1,762 · 5,286 atm ▸ Q<sub>p</sub> = (1,762 × 5,286) / 8,811 = <b>1,057</b>. Como <b>Q &lt; K</b> hay déficit de productos y la reacción avanza hacia la derecha: <b>sí, se forma más H<sub>2</sub></b>. ▸ Los 10 kg de carbón <b>no entran en Q ni en K</b> por ser sólido, y decirlo es parte de lo que se evalúa; que esté en exceso garantiza que no se agote, pero no decide el sentido. ▸ Que ya haya productos cargados tampoco decide nada por sí solo: lo que decide es la comparación numérica Q vs. K.'},

  {st: '1er Recuperatorio, Ej. 3d. Con 55 mol de vapor de agua se forman en el equilibrio 37,6 mol de H<sub>2</sub>. ¿Cuántos kilos de H<sub>2</sub> se obtienen por tonelada de vapor si se trabaja alcanzando el 80 % de la conversión de equilibrio?',
   opts: ['89,5 kg', '61,2 kg', '76,5 kg', '30,4 kg'],
   c: 1,
   ex: 'Conversión de equilibrio = 37,6/55 = <b>68,36 %</b> ▸ conversión de trabajo = 0,80 × 68,36 = <b>54,69 %</b>. Por tonelada: 10<sup>6</sup> g / 18,02 = 55 494 mol de agua ▸ × 0,5469 = 30 350 mol de H<sub>2</sub> ▸ × 2,016 g/mol = <b>61,2 kg</b>. ▸ Los <b>89,5 kg</b> salen de tratar el 80 % como si fuera el rendimiento total: «80 % de la conversión de equilibrio» es el 80 % de 68,36 %, no 80 %. ▸ Los <b>76,5 kg</b> usan la conversión de equilibrio completa, sin el 80 %. ▸ Los <b>30,4 kg</b> son los moles bien calculados pero con M(H<sub>2</sub>) = 1 g/mol en vez de 2,016: el hidrógeno molecular tiene <b>dos</b> átomos.'},

  {st: 'Evaluación integradora 11/07/24, Ej. 1a. Pila Mg(s)/Mg<sup>2+</sup>(10<sup>-2</sup> M)//H<sup>+</sup>(pH=3)/H<sub>2</sub>(0,8 atm)/Pt(s). ¿Cuál es el cociente de reacción Q de la global Mg(s) + 2 H<sup>+</sup> → Mg<sup>2+</sup> + H<sub>2</sub>(g)?',
   opts: ['Q = 8000', 'Q = 8', 'Q = 1,25·10<sup>-4</sup>', 'Q = 0,008'],
   c: 0,
   ex: 'Q = [Mg<sup>2+</sup>]·p(H<sub>2</sub>) / [H<sup>+</sup>]<sup>2</sup> = (10<sup>-2</sup> × 0,8) / (10<sup>-3</sup>)<sup>2</sup> = 8·10<sup>-3</sup> / 10<sup>-6</sup> = <b>8000</b>. ▸ El <b>8</b> es olvidarse del cuadrado de [H<sup>+</sup>], que sale de los <b>2 H<sup>+</sup></b> de la ecuación global; con Q = 8 el potencial daría 2,3129 V en vez de 2,2246 V. ▸ El <b>1,25·10<sup>-4</sup></b> es Q invertido: productos arriba, reactivos abajo. ▸ El <b>0,008</b> es el numerador solo. ▸ Dos reglas que hay que tener automatizadas: el Mg(s) y el Pt(s) son <b>sólidos y no van en Q</b>, y el H<sub>2</sub> entra como <b>presión parcial</b>, no como concentración.'},

  {st: 'Evaluación integradora 11/07/24, Ej. 2c. Para la termita, ΔH = −847 kJ/mol y ΔS = −38,52 J/mol·K. ¿Existe alguna temperatura para la cual la reacción no sea espontánea?',
   opts: ['No: con ΔH negativo es espontánea a toda temperatura', 'Sí, por encima de 21,99 K', 'Sí, por encima de 21 989 K, pero es una temperatura físicamente inalcanzable', 'No se puede decidir sin conocer ΔG°'],
   c: 2,
   ex: 'Con ΔH &lt; 0 y ΔS &lt; 0 la reacción es espontánea a baja temperatura y deja de serlo por encima de T = ΔH/ΔS. Pasando todo a joule: 847 000 / 38,52 = <b>21 989 K</b>. ▸ La opción de los <b>21,99 K</b> es el error clásico de este ítem: dividir 847 (kJ) por 38,52 (J) <b>sin convertir</b>, lo que te lleva a concluir que la termita no es espontánea a temperatura ambiente, exactamente al revés de lo que pasa. ▸ Decir sólo «no» ignora el signo negativo de ΔS, que es el dato que te dieron a propósito. ▸ La respuesta completa es el doble filo: <b>existe matemáticamente y no significa nada en la práctica</b>, porque 21 989 K es casi cuatro veces la temperatura de la superficie del Sol.'},

  {st: 'Evaluación integradora 18/07/24, Ej. 1c. Hay 7,8 g de benceno (0,0999 mol) a 20 °C, con P<sub>v</sub> = 74,7 mmHg. Sabiendo que a partir de 24,5 L ya no queda líquido, ¿cuál es la presión del sistema si el recipiente tiene 30 L?',
   opts: ['0,0983 atm, la presión de vapor', '0,0801 atm', '0,0983 atm sólo si el recipiente está cerrado', '1 atm'],
   c: 1,
   ex: 'Como 30 L &gt; 24,5 L, <b>ya no queda líquido</b>: el sistema es un gas insaturado y la presión sale de la ecuación de estado, P = nRT/V = 0,0999 × 0,0821 × 293,15 / 30 = <b>0,0801 atm</b> (60,9 mmHg). ▸ La presión de vapor sería la respuesta <b>sólo mientras coexistan líquido y vapor</b>, es decir para V ≤ 24,5 L; ahí sí la presión no depende del volumen. ▸ Control de coherencia que valida el resultado: 0,0801 &lt; 0,0983, o sea vapor insaturado, consistente con que no haya líquido. Si te hubiera dado <b>más</b> que P<sub>v</sub>, el cálculo estaría mal: el sistema habría condensado. ▸ 1 atm es el punto de ebullición normal, otra cosa.'},

  {st: '2do Recuperatorio 6/12/24, Ej. 1a. «Un sólido cúbico centrado en el cuerpo tiene el triple de partículas por celda unitaria que uno cúbico simple y un tercio de uno cúbico centrado en caras». ¿Verdadero o falso?',
   opts: ['Verdadero: 3 contra 1 y 3 contra 9', 'Falso sólo en la primera parte: bcc tiene 2 y simple 1', 'Falso en las dos partes: bcc tiene 2, simple 1 y fcc 4', 'Verdadero, pero sólo para sólidos metálicos'],
   c: 2,
   ex: 'Con la regla de los aportes (vértice 1/8, cara 1/2, interior 1): cúbica simple = 8 × 1/8 = <b>1</b>; bcc = 1 + 1 = <b>2</b>; fcc = 1 + 6 × 1/2 = <b>4</b>. ▸ La bcc tiene <b>el doble</b> de la simple, no el triple; y <b>la mitad</b> de la fcc, no un tercio. <b>Las dos afirmaciones son falsas y hay que refutar las dos</b>: si sólo desmentís una, te llevás medio ítem de los 10 que vale. ▸ El conteo no depende de que el sólido sea metálico, iónico o molecular: es geometría de la celda.'},

  {st: '2do Recuperatorio 6/12/24, Ej. 3c. Titular 3 mL de vinagre consumió 17,85 mL de NaOH 0,1250 M. Si se reemplaza el titulante por Ca(OH)<sub>2</sub> de igual molaridad y la muestra pasa a 5 mL, ¿cuántos mL se gastan?',
   opts: ['29,75 mL', '14,88 mL', '17,85 mL', '59,50 mL'],
   c: 1,
   ex: 'Dos correcciones encadenadas: la muestra es <b>5/3 veces mayor</b> (más ácido) y el Ca(OH)<sub>2</sub> aporta <b>2 OH<sup>-</sup> por fórmula</b> a igual molaridad (menos volumen) ▸ 17,85 × (5/3) ÷ 2 = <b>14,88 mL</b>. ▸ Los <b>29,75 mL</b> son sólo la primera corrección: te olvidaste del 2 del hidróxido de calcio. ▸ Los <b>59,50 mL</b> multiplican por 2 en vez de dividir. ▸ La reacción que hay que escribir es 2 CH<sub>3</sub>COOH + Ca(OH)<sub>2</sub> → (CH<sub>3</sub>COO)<sub>2</sub>Ca + 2 H<sub>2</sub>O, y la «justificación» que pide el ítem es exactamente la relación 2:1.'},

  {st: 'Parcial 30/05/2025, Ej. 3a. Se ponen 4 mol de SbCl<sub>5</sub> en 3 L a 182 °C; en el equilibrio hay 0,17 mol de Cl<sub>2</sub>. Con K<sub>c</sub> = 2,515·10<sup>-3</sup>, ¿cuánto vale K<sub>p</sub>?',
   opts: ['0,0940', '3782', '2,515·10<sup>-3</sup>', '6,73·10<sup>-5</sup>'],
   c: 0,
   ex: 'K<sub>p</sub> = K<sub>c</sub>(RT)<sup>Δn</sup> con Δn = 2 − 1 = <b>+1</b> ▸ RT = 0,0821 × 455,15 = 37,368 ▸ K<sub>p</sub> = 2,515·10<sup>-3</sup> × 37,368 = <b>0,0940</b>. ▸ Los <b>3782</b> salen de usar R = 8,31 J/mol·K: con K<sub>p</sub> en atm y K<sub>c</sub> en mol/L, R tiene que ser <b>0,0821 L·atm/mol·K</b>. Cuatro órdenes de magnitud de error. ▸ Que K<sub>p</sub> sea igual a K<sub>c</sub> pasaría sólo si Δn = 0. ▸ El 6,73·10<sup>-5</sup> es dividir por RT en vez de multiplicar. ▸ Control de sensatez: como Δn &gt; 0 y RT &gt; 1, tiene que dar <b>K<sub>p</sub> &gt; K<sub>c</sub></b>. Y ojo: Δn sale de <b>los coeficientes de la ecuación</b>, no de los 0,17 mol que reaccionaron.'},

  {st: '2do Recuperatorio 27/06/25, Ej. 1b. Se quieren preparar 20 g de CrCl<sub>3</sub> (0,1263 mol) según K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> + 14 HCl → 2 CrCl<sub>3</sub> + 3 Cl<sub>2</sub> + 2 KCl + 7 H<sub>2</sub>O, con rendimiento 80 % y pureza de la droga 75 %. ¿Qué masa de dicromato impuro hace falta?',
   opts: ['23,22 g', '18,58 g', '30,96 g', '13,93 g'],
   c: 2,
   ex: 'n(K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>) teórico = 0,1263/2 = 0,06315 mol ▸ con 80 % de rendimiento: <b>÷0,80</b> = 0,07894 mol ▸ × 294,18 g/mol = <b>23,22 g de dicromato puro</b> ▸ con 75 % de pureza: <b>÷0,75</b> = <b>30,96 g de droga impura</b>. ▸ Los <b>23,22 g</b> son la masa pura, o sea el paso anterior: falta aplicar la pureza. ▸ Los <b>18,58 g</b> y los <b>13,93 g</b> salen de <b>multiplicar</b> por 0,80 y/o 0,75 en vez de dividir. ▸ La regla que evita los cuatro casos: yendo del producto hacia el reactivo, rendimiento y pureza <b>siempre dividen</b>, y la masa impura tiene que ser <b>mayor</b> que la pura. Si te da menor, invertiste algo.'}

]);

registerReveals('fiuba-quimica-libre', '4', [

  {st: '<b>Parcial Química Básica CB040 · Curso 1 · 31/05/24 · Ejercicio 1</b> (35 pts).<br><br>«En la producción industrial del ácido nítrico se obtiene, en la primera etapa óxido nítrico a partir de amoniaco y oxígeno según la siguiente reacción: 2 NH<sub>3</sub>(g) + 4 O<sub>2</sub>(g) → N<sub>2</sub>O<sub>5</sub>(g) + 3 H<sub>2</sub>O(g), se sabe además que 0,044 moles de NH<sub>3</sub> reaccionan con oxígeno y con un rendimiento del 90 %:<br>a) Calcule cuántos litros de vapor de agua medidos a 125 °C y 1 atm se forman.<br>b) ¿Cuántos moles de oxígeno serán necesarios para que la reacción ocurra?.<br>c) Dibuje la estructura de Lewis del amoniaco y del óxido nítrico y analice cual de los dos tiene mayor punto de ebullición. Justifique en función de sus estructuras y las fuerzas intermoleculares que se establecen.»',
   ans: 'a) 1,94 L · b) 0,088 mol de O<sub>2</sub> · c) el amoníaco, por puente de hidrógeno.',
   sol: '<b>a)</b> La ecuación viene balanceada (N 2/2, H 6/6, O 8/8). Relación 2 NH<sub>3</sub> : 3 H<sub>2</sub>O y el rendimiento se aplica al producto:<pre class="code-block">n(H2O) = 0,044 × (3/2) × 0,90 = 0,0594 mol<br>V = nRT/P = 0,0594 × 0,0821 × 398,15 / 1 = 1,94 L</pre>Con la presión en atm va R = 0,0821 L·atm/mol·K, y 125 °C son 398,15 K.<br><br><b>b)</b> Relación 2 NH<sub>3</sub> : 4 O<sub>2</sub> = 1 : 2 ▸ <b>0,088 mol de O<sub>2</sub></b>. El rendimiento no entra: dice cuánto producto obtenés, no cuánto reactivo cargás. <span class="muted">Si interpretás que sólo avanza el 90 %, el O<sub>2</sub> consumido sería 0,0792 mol; declará el supuesto.</span><br><br><b>c)</b> NH<sub>3</sub>: tres enlaces N–H y un par libre ▸ pirámide trigonal ▸ polar ▸ <b>puente de hidrógeno</b>. NO: 11 electrones de valencia, número impar, prácticamente apolar ▸ sólo dispersión de London. Gana el <b>amoníaco</b>.<br><br><b>Errata:</b> el enunciado llama «óxido nítrico» (que es NO) al N<sub>2</sub>O<sub>5</sub> que escribe en la ecuación. Resolvé c) para NO y aclaralo por escrito.'},

  {st: '<b>Parcial Curso 1 · 31/05/24 · Ejercicio 3</b> (30 pts).<br><br>«El ácido benzoico (C<sub>6</sub>H<sub>5</sub>COOH) es un buen conservante de alimentos ya que inhibe el crecimiento bacteriano, siempre que el pH del medio creado sea igual o inferior a 4,0. Dato: pKa (ácido benzoico) = 6,5<br>a) Escriba los balances y expresiones que describen los equilibrios en el sistema dado y calcule la mínima concentración inicial del ácido (en molaridad) para preparar una solución conservante explicitando las suposiciones que realiza en los cálculos.<br>b) Calcule % de ionización (alfa) del ac. benzoico<br>c) Si se quiere sustituir el ac. benzoico por ácido clorhídrico, calcular la concentración molar de este último para obtener una solución con el mismo pH. Justificar su respuesta»',
   ans: 'a) C = 3,17·10<sup>-2</sup> M · b) α = 0,32 % · c) HCl 1,0·10<sup>-4</sup> M, 317 veces menos.',
   sol: '<b>a)</b> Los balances valen la mitad del ítem: escribilos siempre.<pre class="code-block">C6H5COOH ⇌ H+ + C6H5COO−   Ka = [H+][C6H5COO−]/[C6H5COOH]<br>H2O ⇌ H+ + OH−             Kw = [H+][OH−] = 1,0·10−14<br>Masa:  C = [C6H5COOH] + [C6H5COO−]<br>Carga: [H+] = [C6H5COO−] + [OH−]<br>Suposiciones: [OH−] despreciable → [H+] = [C6H5COO−]<br>              poco disociado    → [C6H5COOH] ≈ C</pre>Con pH 4,0, [H<sup>+</sup>] = 1,0·10<sup>-4</sup> M; K<sub>a</sub> = 10<sup>-6,5</sup> = 3,162·10<sup>-7</sup>.<pre class="code-block">C = [H+]²/Ka + [H+] = 3,162·10−2 + 1,0·10−4 = 3,17·10−2 M<br>(con la aproximación pura: 3,16·10−2 M, 0,3 % de diferencia)</pre><b>b)</b> α = 1,0·10<sup>-4</sup> / 3,17·10<sup>-2</sup> = <b>0,32 %</b>, que es lo que justifica la suposición.<br><br><b>c)</b> El HCl es fuerte: C = [H<sup>+</sup>] = <b>1,0·10<sup>-4</sup> M</b>. La justificación es el cociente: <b>317 veces menos</b> que el ácido débil para el mismo pH.<br><br><b>Errata:</b> el pK<sub>a</sub> real del ácido benzoico es <b>4,20</b>. Resolvé con el 6,5 del examen y aclaralo; con 4,20 la respuesta sería 2,58·10<sup>-4</sup> M y la aproximación dejaría de valer.'},

  {st: '<b>Parcial Curso 2 · Ejercicio 1</b> (35 pts).<br><br>«El cloruro de sodio reacciona con el ácido sulfúrico para formar sulfato de sodio y ácido clorhídrico según la siguiente reacción: 2 NaCl(s) + H<sub>2</sub>SO<sub>4</sub>(ac) —&gt; Na<sub>2</sub>SO<sub>4</sub>(ac) + 2 HCl(ac). Si se sabe que se forman 3,66 moles de HCl.<br>a) Calcule el volumen necesario de solución de ácido sulfúrico del 98 % m/m y densidad 1,83 g/mL<br>b) Si se utilizan 500 g de cloruro de sodio del 71 % de pureza identifique cuál será el reactivo limitante y calcule los moles que no reaccionaron del reactivo en exceso<br>c) Realice la estructura de lewis de ambos reactivos e indique cuál tendrá mayor punto de fusión. Justifique adecuadamente su respuesta»',
   ans: 'a) 100,1 mL · b) limitante H<sub>2</sub>SO<sub>4</sub>, sobran 2,41 mol de NaCl · c) el NaCl.',
   sol: '<pre class="code-block">a)  n(H2SO4) = 3,66 mol HCl / 2 = 1,83 mol<br>    m(H2SO4)    = 1,83 × 98,08 = 179,49 g<br>    m(solución) = 179,49 / 0,98 = 183,15 g<br>    V = 183,15 / 1,83 g/mL = 100,1 mL<br><br>b)  m(NaCl puro) = 500 × 0,71 = 355 g<br>    n(NaCl) = 355 / 58,44 = 6,075 mol ; hacen falta 3,66 mol<br>    6,075 &gt; 3,66 → NaCl en exceso, H2SO4 limitante<br>    sobran 6,075 − 3,66 = 2,41 mol de NaCl</pre>El 98 % m/m es <b>masa sobre masa</b>: divide la masa de soluto para dar masa de solución. La densidad recién entra al final para pasar de gramos a mililitros. Invertir ese orden es el error del ítem.<br><br><b>c)</b> NaCl: <b>sólido iónico</b>, red de Na<sup>+</sup> y Cl<sup>-</sup> con fuerzas ion-ion. H<sub>2</sub>SO<sub>4</sub>: <b>molecular</b>, covalente polar, con puente de hidrógeno entre moléculas. Las fuerzas ion-ion son mucho más intensas ▸ <b>el NaCl tiene el punto de fusión más alto</b>. El argumento es la energía reticular: atracción proporcional al producto de las cargas e inversamente proporcional a la distancia.'},

  {st: '<b>Parcial Curso 3 · Ejercicio 3</b> (30 pts).<br><br>«El vinagre de cocina es una solución acuosa que tiene una concentración de 5 % m/V de ácido acético. Dato: Ka (CH<sub>3</sub>COOH) = 1,75x10<sup>-5</sup><br>a) Escriba los balances y expresiones que describen los equilibrios en el sistema dado y calcule el pH que tiene el vinagre explicitando las suposiciones que realiza en los cálculos..<br>b) Calcule % de ionización (alfa) del ácido acético en el vinagre<br>c) Calcule en pH que tendrá la solución resultante de mezclar 5 mL de vinagre con 95 mL de agua (considere que los volúmenes son aditivos)»',
   ans: 'a) C = 0,8326 M, pH = 2,42 · b) α = 0,458 % · c) pH = 3,07.',
   sol: '<b>a)</b> El 5 % m/V son 5 g en 100 mL, o sea 50 g/L.<pre class="code-block">C = 50 / 60,05 g/mol = 0,8326 M<br><br>CH3COOH ⇌ H+ + CH3COO−     Ka = [H+][CH3COO−]/[CH3COOH]<br>Masa:  C = [CH3COOH] + [CH3COO−]<br>Carga: [H+] = [CH3COO−] + [OH−]<br>Suposiciones: [OH−] despreciable y [CH3COOH] ≈ C<br><br>[H+] = √(Ka·C) = √(1,75·10−5 × 0,8326) = 3,817·10−3 M<br>pH = 2,42</pre><b>b)</b> α = 3,817·10<sup>-3</sup> / 0,8326 = 4,58·10<sup>-3</sup> = <b>0,458 %</b>. Muy por debajo del 5 %: la suposición se sostiene.<br><br><b>c)</b> 5 mL en 100 mL finales es una dilución <b>1:20</b>:<pre class="code-block">C\' = 0,8326 / 20 = 0,04163 M<br>[H+] = √(1,75·10−5 × 0,04163) = 8,535·10−4 M<br>pH = 3,07</pre>Diluir 20 veces <b>no</b> sube el pH en log(20) = 1,3 unidades: sube 0,65, porque al diluir un ácido débil <b>aumenta el grado de disociación</b> y el [H<sup>+</sup>] cae sólo con la raíz de la concentración. Ése es el concepto que evalúa el ítem.'},

  {st: '<b>1er Recuperatorio · 14/06/24 · Ejercicio 2</b> (30 pts).<br><br>«Se sabe que la combustión completa de un mol de combustible líquido que sólo contiene C e H, produce 220 g de CO<sub>2</sub> gaseoso y 108 g de H<sub>2</sub>O líquida. Se sabe ademas que la entalpia de combustion para dicho combustible es de −3537,06 kJ/mol.<br>a) Con los datos de que dispone indique cual es la fórmula molecular del combustible propuesto e indique la fórmula desarrollada y el nombre de una posible sustancia que cumpla con la consigna del enunciado justificando su razonamiento. Escriba la ecuación termoquímica para el combustible.<br>b) Si se sabe además que ΔH°f CO<sub>2</sub>(g) = −393,5 kJ/mol y ΔH°f H<sub>2</sub>O(l) = −286,0 kJ/mol, calcule la entalpia de formacion para el combustible líquido propuesto. Justifique su respuesta.<br>c) Calcule la variación de energía interna para la combustión de 1 mol del combustible líquido a 25 C. Justifique su razonamiento»',
   ans: 'a) C<sub>5</sub>H<sub>12</sub>, n-pentano · b) ΔH°<sub>f</sub> = −146,44 kJ/mol · c) ΔU = −3529,63 kJ/mol.',
   sol: '<pre class="code-block">a) n(CO2) = 220 / 44,01 = 5,00 mol → 5 átomos de C<br>   n(H2O) = 108 / 18,02 = 5,99 mol → 12 átomos de H<br>   Fórmula molecular: C5H12 (M = 72,15 g/mol)<br>   Desarrollada: CH3–CH2–CH2–CH2–CH3   Nombre: n-pentano<br><br>   C5H12(l) + 8 O2(g) → 5 CO2(g) + 6 H2O(l)   ΔH = −3537,06 kJ/mol<br><br>b) ΔH°comb = [5·ΔH°f(CO2) + 6·ΔH°f(H2O)] − ΔH°f(C5H12)<br>   −3537,06 = −3683,5 − ΔH°f<br>   ΔH°f(C5H12, l) = −146,44 kJ/mol<br><br>c) Δn(gas) = 5 − 8 = −3   (combustible y agua líquidos: no cuentan)<br>   Δn·R·T = (−3)(8,31·10−3)(298,15) = −7,43 kJ/mol<br>   ΔU = −3537,06 + 7,43 = −3529,63 kJ/mol</pre>Como te dan <b>un mol</b> de combustible, los moles de CO<sub>2</sub> son directamente los átomos de C y los de H<sub>2</sub>O el doble de los de H. El balance del O<sub>2</sub>: 5×2 + 6 = 16 átomos ▸ 8 O<sub>2</sub>.<br><br>La justificación de c): el sistema <b>se contrae</b>, el entorno hace trabajo sobre él y por eso |ΔU| &lt; |ΔH|. La diferencia es el 0,2 %: con líquidos y sólidos, ΔU ≈ ΔH.'},

  {st: '<b>1er Recuperatorio · 14/06/24 · Ejercicio 3</b> (40 pts).<br><br>«Un método industrial de obtención de combustible gaseoso emplea la reacción entre el carbón y el vapor de agua: C(s) + H<sub>2</sub>O(g) ⇌ CO(g) + H<sub>2</sub>(g). En un ensayo a 800 °C se determinó que cuando las presiones parciales del monóxido de carbono y el hidrógeno son iguales a 6,151 atm y la del vapor de agua 2,649 atm el sistema se halla en equilibrio.<br>a) En un recipiente cerrado de 500 L se colocan 10 kg de carbón, 50 moles de vapor de agua y un reciclo de 10 moles de CO y 30 moles de H<sub>2</sub>. Si se mantiene la temperatura constante a 800 °C, ¿se obtendrá más hidrógeno?. Justifique el razonamiento utilizado.<br>b) Se sabe que a la temperatura de trabajo ΔH°f(H<sub>2</sub>O(g)) = −241820 J/mol y ΔH°f(CO(g)) = −110500 J/mol. Explique en detalle cómo aplica el principio de Le Chatelier para decidir si conviene trabajar a alta o baja temperatura a los efectos de obtener más combustible.<br>c) Analice si un aumento de presión sobre el sistema reaccionante conduce o no a más producto.<br>d) Cuando en el reactor con carbón en exceso se colocan 55 moles de vapor de agua, al alcanzar el equilibrio se forman 37,6 moles de H<sub>2</sub>. Calcular los kilos de H<sub>2</sub> que se obtienen por cada tonelada de vapor de agua si se trabaja alcanzando el 80 % de la conversión de equilibrio en esas condiciones.»',
   ans: 'a) Sí (Q = 1,06 &lt; K<sub>p</sub> = 14,28) · b) alta temperatura (ΔH = +131,32 kJ/mol) · c) no · d) 61,2 kg de H<sub>2</sub> por tonelada.',
   sol: '<pre class="code-block">Kp = p(CO)·p(H2)/p(H2O) = 6,151² / 2,649 = 14,28<br>   (el carbón es sólido: NO entra en la expresión)<br><br>a) T = 1073,15 K ; RT/V = 0,0821 × 1073,15 / 500 = 0,17621 atm/mol<br>   p(H2O) = 8,811 ; p(CO) = 1,762 ; p(H2) = 5,286 atm<br>   Qp = (1,762 × 5,286) / 8,811 = 1,057  &lt;  Kp = 14,28<br>   → avanza hacia PRODUCTOS: SÍ se obtiene más hidrógeno<br><br>b) ΔH°r = (−110500) − (−241820) = +131 320 J/mol = +131,32 kJ/mol<br>   ENDOTÉRMICA → el calor actúa como reactivo → subir T desplaza<br>   hacia productos → CONVIENE ALTA TEMPERATURA<br><br>c) Δn(gas) = 2 − 1 = +1 (el carbón es sólido)<br>   Más presión desplaza hacia menos moles de gas = reactivos<br>   → NO conduce a más producto<br><br>d) conversión de equilibrio = 37,6 / 55 = 68,36 %<br>   conversión de trabajo   = 0,80 × 68,36 = 54,69 %<br>   n(H2O) por tonelada = 1 000 000 / 18,02 = 55 494 mol<br>   n(H2) = 55 494 × 0,5469 = 30 350 mol<br>   m(H2) = 30 350 × 2,016 = 61 186 g = 61,2 kg</pre>La trampa del ítem d): «<b>80 % de la conversión de equilibrio</b>» es el 80 % de 68,36 %, o sea 54,69 %, no 80 %. Y 1 tonelada son 10<sup>6</sup> g.'},

  {st: '<b>Evaluación integradora · 18/07/24 · Parte A · Ejercicio 1</b> (19 pts).<br><br>«En un recipiente de volumen variable se introducen 7,8 gr de benceno (C<sub>6</sub>H<sub>6</sub>) líquido a 20 ºC. Datos: P<sub>v</sub>(benceno)(20 ºC) = 74,7 mm Hg ; 760 mmHg = 1 atm.<br>a) Calcular cuál debería ser el volumen del recipiente para que exista un equilibrio equimolar líquido-vapor. indique qué consideraciones hace para los cálculos.<br>b) Calcular a partir de qué volumen existirá sólo vapor a esa temperatura. Justifique<br>c) Calcule la presión del sistema si el recipiente tiene un volumen de 30 L.»',
   ans: 'a) 12,2 L · b) a partir de 24,5 L · c) 0,0801 atm (60,9 mmHg).',
   sol: 'La idea de fondo: <b>mientras haya líquido, la presión es la presión de vapor y no depende del volumen</b>; lo que cambia con el volumen es cuánto líquido se evaporó.<pre class="code-block">M(C6H6) = 78,11 g/mol → n total = 7,8 / 78,11 = 0,0999 mol<br>Pv = 74,7 / 760 = 0,09829 atm ; T = 293,15 K<br><br>a) equimolar → n(vapor) = 0,04993 mol<br>   V = 0,04993 × 0,0821 × 293,15 / 0,09829 = 12,2 L<br><br>b) todo vapor → n(vapor) = 0,0999 mol<br>   V = 0,0999 × 0,0821 × 293,15 / 0,09829 = 24,5 L<br>   → para V ≥ 24,5 L no queda líquido<br><br>c) 30 L &gt; 24,5 L → todo vapor, insaturado<br>   P = nRT/V = 0,0999 × 0,0821 × 293,15 / 30 = 0,0801 atm = 60,9 mmHg</pre><b>Consideraciones</b> del ítem a), que valen puntos: el volumen del líquido es despreciable frente al del vapor, y el vapor se comporta como gas ideal.<br><br><b>Control</b> del ítem c): 0,0801 atm &lt; 0,0983 atm de presión de vapor ▸ vapor insaturado, coherente con que no quede líquido. Si hubiera dado <b>más</b> que P<sub>v</sub>, el sistema habría condensado y la presión sería exactamente P<sub>v</sub>.'},

  {st: '<b>Evaluación integradora · 18/07/24 · Parte A · Ejercicio 2</b> (21 pts).<br><br>«Se agregan 0,5 g de hidróxido de sodio, NaOH, a 400 mL de una disolución acuosa de ácido clorhídrico, HCl(ac), cuyo pH = 2.<br>a) Escribir la ecuación correspondiente a la reacción y los balances correspondientes.<br>b) Calcular el pH de la disolución resultante. Suponer que no se produce variación en el volumen al añadir el sólido a la disolución acuosa.<br>c) Calcular el volumen de una solución de hidróxido de calcio, Ca(OH)<sub>2</sub> 0,15 M que sería necesario agregar a la disolución de ácido clorhídrico inicial, si se quisiera alcanzar un pH = 7.»',
   ans: 'b) pH = 12,33 · c) 13,3 mL de Ca(OH)<sub>2</sub> 0,15 M.',
   sol: '<pre class="code-block">a) NaOH(s) + HCl(ac) → NaCl(ac) + H2O(l)<br>   Carga: [Na+] + [H+] = [Cl−] + [OH−]<br>   Masa:  [Na+] = C(NaOH) ; [Cl−] = C(HCl)<br><br>b) n(NaOH) = 0,5 / 40,00 = 0,0125 mol<br>   pH = 2 → [HCl] = 10−2 M → n(HCl) = 0,01 × 0,400 = 0,004 mol<br>   0,0125 &gt; 0,004 → sobra BASE<br>   n(OH−) exceso = 0,0085 mol ; [OH−] = 0,0085 / 0,400 = 0,02125 M<br>   pOH = 1,67 → pH = 12,33<br><br>c) equivalencia: n(OH−) = n(H+) = 0,004 mol<br>   Ca(OH)2 aporta 2 OH− → n = 0,004 / 2 = 0,002 mol<br>   V = 0,002 / 0,15 = 0,01333 L = 13,3 mL</pre>Dos cosas que se cobran. En <b>b)</b>, los dos son electrolitos fuertes: <b>no hay equilibrio, hay una resta</b>, y manda lo que sobra. En <b>c)</b>, el pH 7 se justifica porque el producto es <b>CaCl<sub>2</sub>, sal de ácido fuerte con base fuerte</b>, que no hidroliza: en el punto de equivalencia el pH es exactamente 7. Con un ácido débil en lugar del HCl la equivalencia caería en pH básico y el ítem cambiaría por completo.<br><br>Y el clásico: el Ca(OH)<sub>2</sub> aporta <b>2 OH<sup>-</sup> por fórmula</b>. Sin ese 2 el volumen te da 26,7 mL.'},

  {st: '<b>2do Recuperatorio · 6/12/2024 · Ejercicio 2</b> (30 pts).<br><br>«La reacción en fase gaseosa CO(g) + H<sub>2</sub>O(g) → CO<sub>2</sub>(g) + H<sub>2</sub>(g) se efectúa a temperatura constante y presión constante de 1 atm. Cuando se forman 200 moles de hidrógeno gaseoso el calor liberado es 8232 kJ. Se pide: a) escribir la ecuación termoquímica correspondiente; b) Con los datos de que dispone, determinar la entalpía de combustión estándar del monóxido de carbono y escribir su ecuación termoquímica c) calcular los kilos de vapores de etanol a 78 °C (pto de ebullición del etanol) y 1 atm que se pueden obtener si se logra transferir el 70 % del calor producido por la reacción del enunciado a etanol líquido que se halla a 25 °C y 1 atm.<br>Datos: ΔH°f_H<sub>2</sub>O(g) = −241,82 kJ/mol; ΔH°f_CO<sub>2</sub>(g) = −393,51 kJ/mol; ΔHvap_C<sub>2</sub>H<sub>6</sub>O = 43,5 kJ/mol; CpC<sub>2</sub>H<sub>6</sub>O(l) = 0,112 kJ/mol.°C»',
   ans: 'a) ΔH° = −41,16 kJ/mol · b) ΔH°<sub>comb</sub>(CO) = −282,98 kJ/mol · c) 5,37 kg de vapores de etanol.',
   sol: '<pre class="code-block">a) ΔH = −8232 kJ / 200 mol = −41,16 kJ/mol<br>   CO(g) + H2O(g) → CO2(g) + H2(g)      ΔH° = −41,16 kJ/mol<br><br>b) ΔH°r = ΔH°f(CO2) − ΔH°f(CO) − ΔH°f(H2O,g)<br>   −41,16 = −393,51 − ΔH°f(CO) + 241,82<br>   ΔH°f(CO) = −110,53 kJ/mol<br><br>   CO(g) + ½ O2(g) → CO2(g)<br>   ΔH°comb = −393,51 − (−110,53) = −282,98 kJ/mol<br><br>c) Q útil = 0,70 × 8232 = 5762,4 kJ<br>   q por mol de etanol = 0,112 × (78 − 25) + 43,5<br>                       = 5,936 + 43,5 = 49,436 kJ/mol<br>   n = 5762,4 / 49,436 = 116,56 mol<br>   m = 116,56 × 46,07 = 5370 g = 5,37 kg</pre>El ítem b) es un <b>rodeo de dos escalones</b>: no te dan la ΔH°<sub>f</sub> del CO, hay que sacarla de la reacción del enunciado y recién después armar la combustión. Control cruzado: ese −110,53 kJ/mol coincide con el −110 500 J/mol que la cátedra imprime en el 1er Recuperatorio del 14/06/24.<br><br>El ítem c) repite la estructura del secadero de los parciales de curso: <b>calentar hasta la temperatura de cambio de fase y después cambiar de fase</b>. Acá el Cp ya viene en kJ/mol·°C: no hay que convertir.'},

  {st: '<b>2do Recuperatorio · 27/06/25 · Ejercicio 2</b> (30 pts).<br><br>«Se queman completamente 700 moles de propano y 300 moles de butano. El 90 % del calor total que produce la combustión se transfiere a 900 kg de agua que se halla a −5 °C y permanece a 1 atm. Se pide: a) Escribir las ecuaciones termoquímicas para cada uno de los combustibles b) calcular el calor total generado en la combustión; c) determinar la situación final del agua (estados de agregación y cantidad de fases) que se halla inicialmente como hielo y bosquejar la curva de calentamiento correspondiente al proceso justificando su respuesta.<br>Datos: ΔH<sub>comb_propano</sub> = −2220 kJ/mol; ΔH<sub>comb_butano</sub> = −2878,6 kJ/mol; ΔH<sub>fusión_agua</sub> = 6,03 kJ/mol; ΔH<sub>vaporización_agua</sub> = 40,70 kJ/mol; Cp<sub>agua_sólida</sub> = 33,60 J/(mol.K); Cp<sub>agua_líquida</sub> = 75,23 J/(mol.K); Cp<sub>agua_vapor</sub> = 36,28 J/(mol.K).»',
   ans: 'b) 2 417 580 kJ · c) dos fases a 100 °C: ≈ 660 kg de vapor y ≈ 240 kg de líquido (73,3 % vaporizado).',
   sol: '<pre class="code-block">a) C3H8(g)  + 5 O2(g)    → 3 CO2(g) + 4 H2O(l)   ΔH = −2220,0 kJ/mol<br>   C4H10(g) + 13/2 O2(g) → 4 CO2(g) + 5 H2O(l)   ΔH = −2878,6 kJ/mol<br><br>b) Q = 700 × 2220 + 300 × 2878,6 = 2 417 580 kJ<br><br>c) Q transferido = 0,90 × 2 417 580 = 2 175 822 kJ<br>   n(H2O) = 900 000 / 18,02 = 49 944 mol<br><br>   tramo 1 · hielo −5 → 0 °C : 49 944 × 0,0336 × 5 =     8 391 kJ<br>   tramo 2 · fusión a 0 °C   : 49 944 × 6,03      =   301 165 kJ<br>   tramo 3 · agua 0 → 100 °C : 49 944 × 0,07523×100 =  375 733 kJ<br>   tramo 4 · vaporización    : 49 944 × 40,70     = 2 032 741 kJ<br><br>   acumulado hasta el tramo 3 : 685 289 kJ  (alcanza)<br>   acumulado hasta el tramo 4 : 2 718 030 kJ (NO alcanza)<br><br>   sobrante = 2 175 822 − 685 289 = 1 490 533 kJ<br>   n vaporizada = 1 490 533 / 40,70 = 36 622 mol = 73,3 %<br>   vapor 659,9 kg  ·  líquido 240,1 kg</pre>Se resuelve <b>por etapas acumuladas</b>: comparás el calor disponible con el acumulado de cada tramo hasta que se corta en el medio de uno. Acá se corta en la vaporización ▸ <b>situación final: agua a 100 °C en dos fases</b>.<br><br>La <b>curva</b>: rampa corta de −5 a 0 °C ▸ meseta a 0 °C ▸ rampa larga de 0 a 100 °C ▸ meseta a 100 °C <b>cortada al 73 %</b>. El punto final va sobre la meseta, no después: eso demuestra que hay dos fases. El Cp del vapor <b>no se usa</b>: es un dato distractor.'}

]);

